# Own-wording magic items of Valda's Spire of Secrets (2014 rules), Portal Chalk to Émigré Manuscript, plus the magic variants.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

add("Portal Chalk", "Wondrous Item", "Very Rare", 0, "Two pieces of chalk, one glowing orange and one blue, each with 10 uses. As an action, spend a use to draw a round or rectangular portal on a solid stone surface big enough for a Medium creature. It links at once to the most recent portal drawn with the other color, and unlinks any other portals made by these two pieces. A linked portal is a glowing frame filled with opaque mist and works as a magic gate: anything that enters leaves through the other as if they were side by side. An unlinked portal is plain chalk.", ch=[10, "0", "never"])
add("Potion of Mirrored Eyes", "Potion", "Uncommon", 0, "For 1 minute you are immune to any effect that can be avoided by looking away, such as a medusa's petrifying gaze, and can look at such creatures safely.")
add("Puzzle Box", "Wondrous Item", "Rare", 0, "A cubic box that often holds items far stronger than itself. It holds 1 cubic foot. Its contents cannot be targeted by divination or seen through divination sensors. Once closed, it opens only by solving its puzzle: work the mechanism for 24 hours, then pass a DC 23 Intelligence check. Closing the box is an action and scrambles the puzzle.")
add("Replacement Man", "Wondrous Item", "Uncommon", 1, "A humanoid figurine. When damage would drop you to 0 hit points while you are attuned to it, you drop to 1 hit point instead and the figurine fades away with a sad smile.")
add("Replica Clay", "Wondrous Item", "Rare", 0, "A lump of clay. Touch it to an object that fits in a 5-ft cube and it molds into an exact copy in color and texture, even imitating visual magic such as glowing runes. Touch shows it is clay, since it gives under real force, but it looks identical. Once shaped, the clay becomes nonmagical.")
add("Reaper's Bullet", "Weapon", "Legendary", 0, "A bullet forged by the reaper and cut with runes of death. A creature it hits dies.")
add("Reverberating Shield", "Armor", "Very Rare", 1, "A Shield that gives an extra +1 to AC. When a creature misses you with a melee weapon attack while you hold it, that creature makes a DC 15 Dexterity save. On a failure it drops its weapon, which lands 15 ft away from you. If the weapon cannot be dropped, such as a dragon's bite or claws, the attacker has Disadvantage on weapon attacks until the end of its turn.", fx={"ac": 1}, base=["Shield"])
add("Ring of Barrels", "Ring", "Uncommon", 1, "A ring with 6 charges that regains 1d6 at dawn. As an action, spend 1 to 3 charges to summon that many empty barrels in spaces next to you. Each is 6 ft high and 4 ft across, fills the space of a Medium creature, gives cover against ranged attacks and weighs 150 lb (an action to move). You can place one around an incapacitated Medium creature to restrain it, or around a Small or smaller creature to trap it. A creature breaks out with a DC 22 Strength check.", ch=[6, "1d6", "dawn"])
add("Ring of Icebergs", "Ring", "Very Rare", 0, "As a Bonus Action, or a Reaction when an attacker you can see hits you, spin the jewel so it grows into a hollow block of clear ice around you. It fills your space, pushes other creatures out to the nearest free space and ends any grapple you are in. You can move at most 6 inches inside, and no spell or effect passes through the ice. It is an object with AC 10 and 100 hit points, takes as much of the triggering damage as possible if made as a Reaction, is immune to Cold, Poison and Psychic, and is vulnerable to Fire. It lasts up to 1 minute, until destroyed, or until you stop the spinning with a Bonus Action. After one use it cannot be used again until the next dawn.", ch=[1, "1", "dawn"])
add("Ring of Salvation", "Ring", "Uncommon", 1, "If you fail a saving throw while attuned, you can choose to succeed instead. After using this, you cannot do so again until the next dawn.", ch=[1, "1", "dawn"])
add("Sandstone Solution", "Potion", "Rare", 0, "A sandy liquid that flows like water in its container. Pour it out as an action. On stone, a 10-ft-deep, 10-ft-radius area turns to mud for 1 hour. On mud, sand or quicksand, a 10-ft-deep, 10-ft-radius area turns to solid stone for 1 hour, with AC 17, 75 hit points and immunity to Psychic and Poison. A creature inside when it hardens makes a DC 14 Dexterity save or is restrained. It breaks free with a DC 20 Strength check or by dealing 25 damage to the stone.")
add("Scroll of Duplication", "Scroll", "Common", 0, "A blank scroll that copies writing. As an action, touch it to something written. It instantly copies up to 500 consecutive words of your choice into a perfect duplicate. It copies only nonmagical text, leaving blank space for illustrations and magical writing such as spellbook pages or glyph of warding. Using it does not trigger traps that go off when the source is read.")
add("Skitterlegs", "Wondrous Item", "Rare", 1, "Brass and mithral legs worn like a backpack that deploy when you are knocked out or paralyzed (not from nonmagical sleep). Set them to Defend or Eliminate and give them a priority list of friends. Deployed, they lift you so you do not count as prone, and attacks against you are not critical hits despite your condition. They make Strength and Dexterity checks and saves at +5 and walk 30 ft. On each of your turns while you are down: Defend: they Dodge or Disengage (chosen when programming) and move toward the highest-priority conscious friend. Eliminate: they move to the nearest hostile and make two melee attacks at +7, dealing 1d8 + 2 Piercing each. If you recover, they stand you up and retract. They work 1 hour per day in total, then collapse and drop you prone.")
add("Smoking pipe of Dragon's Breath", "Wondrous Item", "Rare", 1, "A pipe with 2 charges that regains 1 at dawn. When it holds 1 ounce of smoking herb, use an action and a charge to inhale and breathe out a cone of dragon's flame. Each creature in a 30-ft cone makes a DC 15 Dexterity save, taking 8d6 Fire on a failure or half on a success.", ch=[2, "1", "dawn"])
add("Sorting Beast", "Wondrous Item", "Rare", 0, "A six-legged construct with eyes, legs and antennae at both ends and gauges in the middle. It lifts up to 30 lb. As an action, activate it to gather and sort all loose valuables within 100 ft: coins into neat stacks of 10, and goods such as gems appraised by weight and quality, with results printed on a paper strip. It works until done or switched off as an action. Once per day it can cast identify on one object you choose, with no material components.")
add("Switch Amalgam", "Wondrous Item", "Rare", 1, "A mix of mithral, quicksilver and platinum that bonds to steel so a craftsman can build compound weapons. Attuned, spend a minute heating it to attach it to a weapon or remove it. It holds two weapons at once. Once on two weapons, both become magical with +1 to attack and damage rolls (not if already magical with a bonus), and both gain the Switch property: two forms, swap between them at any time, even between attacks. Unlike other switch weapons, these do not become exotic.", by="Craftsman")
add("Tome of Tongues", "Wondrous Item", "Uncommon", 0, "A book of grammar and vocabulary for one language, charged with magic. Study it for 8 hours over 2 days or fewer and you learn to read, write and speak that language. The tome then loses its magic for good.")
add("Totem of Enmity", "Wondrous Item", "Rare", 0, "A wooden rod carved with evil symbols and curses in every language. As an action, break it while speaking the name of a creature you know to swear vengeance. You have Advantage on attack rolls against that creature indefinitely. It ends if you break another totem of enmity or the creature dies.")
add("Troll Rod", "Weapon", "Uncommon", 1, "A crude pommel with a living troll's arm on one end. As a Bonus Action, give it orders in the troll dialect of Giant to pick things up, drop them or make a fist (typical words: grabbit, leggo, maik'a'fist). Closed into a fist it acts as a magic Mace, and you gain +1 to attack and damage rolls with it.", fx={"atk": 1, "dmg": 1}, base=["Mace"])
add("Universal Knocker", "Wondrous Item", "Uncommon", 0, "A brass door knocker. Hold it against an object and use an action to cast knock on it. It cannot be used again until the next dawn.", ch=[1, "1", "dawn"])
SP["Universal Knocker"] = {"sp": [["Knock", 2]]}
add("Weapon Charms", "Wondrous Item", "Unknown", 0, "A small ornament on a string or chain. As an action, attach it to a weapon (usually the pommel). The weapon becomes magic and needs attunement, even if it was already magic. A weapon holds one charm. Charms: Bat (Uncommon): damage you deal with it cuts the target's hit point maximum by that amount until it finishes a Long Rest, killing it at 0. Blade (Uncommon): +1 to attack and damage rolls (not if the weapon already has a bonus). Die (Uncommon): on a critical hit, any damage die showing its maximum lets you roll one extra die, repeating on maximums, up to twice the original number of dice. Feather (Common): the weapon weighs half and Small creatures can use it even if Heavy. Ghost (Common): it hits creatures on the Ethereal Plane as if on the Material Plane and the reverse. Hook (Common): Bonus Action to teleport it to your hand from the same plane. Lance (Uncommon): once per turn on a melee attack against a creature you see, lunge up to 15 ft first without provoking Opportunity Attacks (even through the air, then you fall if there is no ground). Lightning Bolt (Uncommon): +1d6 Lightning on a hit. Mirror (Rare): Light weapons only. Drawing it with one hand creates a spectral copy in the other with identical stats and magic but no ammunition, which vanishes when either leaves your hand.")
add("Wooden Coin of Lies", "Wondrous Item", "Very Rare", 1, "While attuned you are constantly under the effect of glibness. Curse. Attuning extends the curse to you, and only remove curse or similar magic breaks it. While attuned you cannot deliberately speak the truth. You can be evasive, lie by omission or give half-truths, as long as your words stay deceptive.")
add("Émigré Manuscript", "Wondrous Item", "Rare", 0, "A skull-shaped ancient tome that smells of violets or tiger lilies. Holding it, cast resurrection with no material components. After use it cannot be used again until the next dawn. Curse. Each time you use it, roll a d20 for the result: the spell fails and the caster dies; the target returns as a revenant seeking revenge on the caster; the target returns as a ghost with memories and personality; the spell works but the 100 humanoids nearest the target (not the caster) die; the spell works but the caster rolls twice on the Indefinite Madness table, and dies if both results match; the spell works but the target loses all memories, class levels, proficiencies (including languages) and personality traits; the spell seems to work but the target dies again after 1d10 minutes and only wish can revive it; or the spell works normally.", ch=[1, "1", "dawn"])
SP["Émigré Manuscript"] = {"sp": [["Resurrection", 7]]}

# ---- magic variants (generic rows)
add("Exploding Armor", "Armor", "Rare", 0, "Any armor. As an action while wearing it, cast fireball (save DC 15) centered on yourself, and you take no damage from it. It cannot be used again until the next dawn.", ch=[1, "1", "dawn"])
SP["Exploding Armor"] = {"sp": [["Fireball", 3]]}
for _r, _b, _dc in (("Uncommon", 1, 13), ("Rare", 2, 15), ("Very Rare", 3, 17)):
    add("Khaliber's Iron (%s)" % _r, "Weapon", _r, 1, "Any firearm, blessed by Khaliber, goddess of gunpowder. It makes its own ammunition right after each shot. You gain +%d to attack and damage rolls with it. On a critical hit the bullet explodes: each creature of your choice within 5 ft of the target, other than the target, makes a DC %d Dexterity save, taking Fire damage equal to half the damage dealt on a failure." % (_b, _dc), fx={"atk": _b, "dmg": _b}, by="Gunslinger")
add("Magehunter Blade", "Weapon", "Very Rare", 1, "Any sword. +2 to attack and damage rolls. When you hit a creature under a spell, you can dispel one spell on it of 5th level or lower, and the target takes an extra 1d8 Force per level of that spell (cantrips deal none). After a spell is dispelled, roll a d6. On a result equal to or below the dispelled spell's level, the sword loses this trait until the next dawn.", fx={"atk": 2, "dmg": 2})
add("Magehunter Plate", "Armor", "Very Rare", 1, "A Breastplate, Half Plate or Plate. It has 3 charges and regains all at dusk. When a magical effect lets you make a save for half damage, spend a charge to take no damage on a success and half on a failure. While you wear it, Acid, Cold, Fire, Lightning and Thunder damage from magical sources, and magical healing you receive, are each reduced by 3. When a magic melee weapon damages you, its wielder rolls a d20. On a 10 or lower the weapon's magic is suppressed for 1 hour.", ch=[3, "all", "dusk"])
add("Peacekeeper", "Weapon", "Uncommon", 1, "Any firearm. +1 to attack and damage rolls. As an action, charge its alternate firing mode (light leaks from its joints) and fire a magical bolas at a creature within 60 ft. The creature makes a DC 13 Dexterity save or is knocked prone and restrained (Huge or larger creatures succeed automatically). It can use an action for a DC 13 Strength check to break free. Each failed check tightens the bolas, dealing 1d8 Radiant. After you use this, roll a d6. On a 1 or 2 you cannot use it again until the next dawn.", fx={"atk": 1, "dmg": 1})
add("Thornbow", "Weapon", "Rare", 1, "Any bow with 6 charges, regaining 1d4 + 2 at dawn. As a Bonus Action spend a charge to grow a thorny arrow of your choice. Bramblestrike: on a hit the target makes a DC 15 Strength save or is restrained by vines for up to 1 minute, and can use an action for a DC 15 Strength check to break free. Splinterstrike: on a hit it bursts into splinters, and each creature within 5 ft of the target makes a DC 15 Dexterity save or takes 1d10 Piercing. Overgrowth Volley (3 charges, action): three arrows fly to a point you see within 120 ft and grow brambles that act as wall of thorns, dealing 4d8 instead of 7d8.", ch=[6, "1d4+2", "dawn"])
add("Treant's Bane", "Weapon", "Rare", 1, "Any axe or sword. A plant creature you hit takes an extra 2d6 damage of the weapon's type. The weapon ignores the damage threshold of objects made of wood, vines and other grown materials.")
add("Weapon for Dummies", "Weapon", "Uncommon", 1, "Any martial weapon. While attuned you are proficient with it. It has 3 charges and regains all at dawn. When you miss with it, spend a charge to gain +5 to the attack roll, which can turn the miss into a hit. The weapon cheers when you hit and sneers when you miss.", ch=[3, "all", "dawn"])

for _f, _b in (("Hand", "Hand Crossbow"), ("Heavy", "Heavy Crossbow")):
    add("Glimmerbolt (%s)" % _f, "Weapon", "Very Rare", 1, "A %s with +1 to attack and damage rolls. It has 10 charges and regains 1d6 + 4 at dawn. As part of the Attack action, spend a charge to create and load a radiant bolt. It deals an extra 1d6 on a hit, and its damage is Radiant instead of Piercing. As an action, spend 3 charges to load a blinding bolt and fire it at a point you see within 60 ft, where it bursts in a flash. Each creature within 20 ft makes a DC 17 Constitution save or is Blinded until the end of your next turn. Motes of light then hang there for 1 minute, shedding Bright Light in a 20-ft radius and Dim Light 20 ft farther." % _b, fx={"atk": 1, "dmg": 1}, base=[_b], ch=[10, "1d6+4", "dawn"])
